_FALLBACK_SRC = '# Exact action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Cost: 3.0 per truck and 1.5 per scooter not on its own base after moves;\n# couriers on their own base cost nothing and serve nothing.\n#\n# Conservative fallback: make only one-turn, directly returnable sorties.\n# Every deployed courier returns home on the next call. Thus there are no\n# unpaid travel turns, no persistent targets, and no dependence on turn history.\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 60\nUNIT_TYPES = {\n    "truck": (8, 3.0, 1),\n    "scooter": (3, 1.5, 2),\n}\n\n\ndef preprocess_map(n, edges):\n    """Small static all-pairs distance table, built lazily."""\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        if 0 <= a < n and 0 <= b < n and a != b:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for start in range(n):\n        distance = [n + 1] * n\n        distance[start] = 0\n        queue = [start]\n        for node in queue:\n            for neighbor in adjacency[node]:\n                if distance[neighbor] > n:\n                    distance[neighbor] = distance[node] + 1\n                    queue.append(neighbor)\n        distances.append(distance)\n    return distances\n\n\ndef payout(own_capacity, opponent_capacity, stock):\n    """The specification\'s proportional service rule, including zero cases."""\n    if own_capacity <= 0 or stock <= 0:\n        return 0.0\n    return own_capacity * stock / max(\n        own_capacity + opponent_capacity, stock\n    )\n\n\ndef next_return_step(position, home, speed, distances):\n    """Return directly if possible; otherwise take a shortest legal homeward step."""\n    candidates = [\n        node for node in range(len(distances))\n        if distances[position][node] <= speed\n    ]\n    return min(candidates, key=lambda node: (distances[node][home], node))\n\n\ndef make_plan(obs, distances, conservative=False):\n    n = len(distances)\n    home = int(obs["player_base"])\n    enemy_home = int(obs["opponent_base"])\n    units = obs.get("player_units", {})\n    enemies = obs.get("opponent_units", {})\n    stock = obs.get("stock", [0.0] * n)\n    remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n    plan = {}\n\n    # Returning home is free on the arrival turn. Normal sorties always have\n    # a direct return; shortest-path retreat also handles an arbitrary first call.\n    for uid, (kind, position) in sorted(units.items()):\n        if kind not in UNIT_TYPES:\n            continue\n        if position != home:\n            speed = UNIT_TYPES[kind][2]\n            plan[uid] = next_return_step(position, home, speed, distances)\n\n    if remaining == 0 or conservative:\n        return plan\n\n    # Ignore idle, undeployed enemies rather than inventing their future moves.\n    # For already deployed enemies, budget ALL capacity that could reach each\n    # candidate this turn. This deliberately avoids uncertain marginal fights.\n    opponent_capacity = [0] * n\n    for kind, position in enemies.values():\n        if kind not in UNIT_TYPES or position == enemy_home:\n            continue\n        capacity, _, speed = UNIT_TYPES[kind]\n        for node in range(n):\n            if distances[position][node] <= speed:\n                opponent_capacity[node] += capacity\n\n    allocated = [0] * n\n\n    # Trucks first: efficient high-capacity harvests; scooters fill only\n    # independently profitable residual demand. Ties are deterministic.\n    order = sorted(\n        units,\n        key=lambda uid: (\n            0 if units[uid][0] == "truck" else 1, uid\n        ),\n    )\n    for uid in order:\n        kind, position = units[uid]\n        if kind not in UNIT_TYPES or position != home:\n            continue\n        capacity, cost, speed = UNIT_TYPES[kind]\n        candidates = []\n        for node in range(n):\n            distance = distances[home][node]\n            if node in (home, enemy_home) or distance > speed:\n                continue\n\n            existing = allocated[node]\n            enemy = opponent_capacity[node]\n            marginal = (\n                payout(existing + capacity, enemy, float(stock[node]))\n                - payout(existing, enemy, float(stock[node]))\n            )\n\n            # Current service pays every cost: outward movement and service\n            # occur together, and the next direct return costs zero. Require\n            # a substantial positive margin rather than marginal break-even.\n            if marginal >= cost + 0.75:\n                candidates.append((distance, -marginal, node))\n\n        if candidates:\n            _, _, destination = min(candidates)\n            allocated[destination] += capacity\n            plan[uid] = destination\n\n    return plan\n\n\ndef legal_action(plan, obs, distances):\n    """Validate each independent move against the actual start-of-turn state."""\n    moves = {}\n    units = obs.get("player_units", {})\n    n = len(distances)\n    for uid in sorted(plan):\n        if not isinstance(uid, str) or uid not in units:\n            continue\n        kind, source = units[uid]\n        if kind not in UNIT_TYPES:\n            continue\n        destination = int(plan[uid])\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if distances[source][destination] > UNIT_TYPES[kind][2]:\n            continue\n        if destination != source:\n            moves[uid] = int(destination)\n    return {"moves": moves}\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self._map_key = None\n        self._distances = None\n\n    def act(self, obs):\n        # Bounded work only: at most 13 BFS traversals on cache construction,\n        # then twelve units times thirteen destinations; no search or rollout.\n        budget = float(TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return {"moves": {}}\n        edges = tuple((int(a), int(b)) for a, b in obs.get("edges", []))\n        key = (n, edges)\n        if self._map_key != key:\n            self._distances = preprocess_map(n, edges)\n            self._map_key = key\n\n        # Feedback is handled without historical state: multiple reported\n        # illegal moves signal a bug, so use only validated homeward retreats.\n        conservative = (\n            int(obs.get("n_invalid_actions_last_turn", 0)) >= 2\n            or budget <= 0\n        )\n        plan = make_plan(obs, self._distances, conservative)\n        return legal_action(plan, obs, self._distances)\n'
